import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  HostListener,
  ViewEncapsulation,
  effect,
  input,
  output,
  viewChild,
} from '@angular/core';
import { chipScrollDelta, classifyShelfGesture, panelRoomPx } from './chip-shelf-gesture';

let nextPanelId = 0;

@Component({
  selector: 'dryl-chip-shelf',
  standalone: true,
  templateUrl: './chip-shelf.component.html',
  styleUrl: './chip-shelf.component.scss',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ChipShelfComponent {
  readonly open = input(false);
  readonly openChange = output<boolean>();
  readonly label = input('');
  readonly showTrigger = input(true);
  readonly panelId = `dryl-chip-shelf-${++nextPanelId}`;
  private readonly panelEl = viewChild<ElementRef<HTMLElement>>('panel');
  private readonly triggerEl = viewChild<ElementRef<HTMLButtonElement>>('trigger');
  private gestureX = 0;
  private gestureY = 0;

  constructor() {
    effect(() => {
      if (!this.open()) return;
      queueMicrotask(() => this.fitPanel());
    });
  }

  @HostListener('document:keydown.escape')
  onEscape(): void {
    if (!this.open()) return;
    this.closeFromUser();
  }

  @HostListener('window:resize')
  onResize(): void {
    if (this.open()) this.fitPanel();
  }

  toggle(): void {
    this.openChange.emit(!this.open());
  }

  gestureStart(event: Event): void {
    const touch = (event as TouchEvent).changedTouches[0];
    if (!touch) return;
    this.gestureX = touch.clientX;
    this.gestureY = touch.clientY;
  }

  gestureMove(event: Event): void {
    if (!this.open()) return;
    const touch = (event as TouchEvent).changedTouches[0];
    const panel = this.panelEl()?.nativeElement;
    if (!touch || !panel) return;
    const delta = chipScrollDelta(touch.clientX - this.gestureX, touch.clientY - this.gestureY);
    if (!delta) return;
    panel.scrollTop += delta;
    this.gestureX = touch.clientX;
    this.gestureY = touch.clientY;
  }

  gestureWheel(event: Event): void {
    if (!this.open()) return;
    const panel = this.panelEl()?.nativeElement;
    if (!panel) return;
    panel.scrollTop += (event as WheelEvent).deltaY;
  }

  gestureEnd(event: Event): void {
    if (!this.open()) return;
    const touch = (event as TouchEvent).changedTouches[0];
    if (!touch) return;
    const kind = classifyShelfGesture(touch.clientX - this.gestureX, touch.clientY - this.gestureY);
    if (kind !== 'dismiss') return;
    event.preventDefault();
    event.stopImmediatePropagation();
    this.closeFromUser();
  }

  private closeFromUser(): void {
    this.openChange.emit(false);
    this.triggerEl()?.nativeElement.focus();
  }

  private fitPanel(): void {
    const trigger = this.triggerEl()?.nativeElement;
    const panel = this.panelEl()?.nativeElement;
    if (!trigger || !panel) return;
    const room = panelRoomPx(trigger.getBoundingClientRect().top);
    panel.style.setProperty('--chip-shelf-room', `${room}px`);
    panel.scrollTop = panel.scrollHeight;
  }
}
