export type TooltipPlacement = 'top' | 'bottom' | 'left' | 'right';
export type TooltipPosition = {
  placement: TooltipPlacement;
  top: number;
  left: number;
  arrowX: string;
  arrowY: string;
};

type Rect = Pick<DOMRect, 'top' | 'right' | 'bottom' | 'left' | 'width' | 'height'>;
type Viewport = { width: number; height: number };
type Point = { top: number; left: number };

const VIEWPORT_PADDING = 8;
const TOOLTIP_GAP = 8;

export function calculateTooltipPosition(
  trigger: Rect,
  tooltip: Rect,
  viewport: Viewport,
  preferred: TooltipPlacement,
): TooltipPosition {
  const candidates: Record<TooltipPlacement, Point> = {
    top: {
      top: trigger.top - tooltip.height - TOOLTIP_GAP,
      left: trigger.left + (trigger.width - tooltip.width) / 2,
    },
    bottom: {
      top: trigger.bottom + TOOLTIP_GAP,
      left: trigger.left + (trigger.width - tooltip.width) / 2,
    },
    left: {
      top: trigger.top + (trigger.height - tooltip.height) / 2,
      left: trigger.left - tooltip.width - TOOLTIP_GAP,
    },
    right: {
      top: trigger.top + (trigger.height - tooltip.height) / 2,
      left: trigger.right + TOOLTIP_GAP,
    },
  };
  const opposite: Record<TooltipPlacement, TooltipPlacement> = {
    top: 'bottom',
    bottom: 'top',
    left: 'right',
    right: 'left',
  };
  const order = [preferred, opposite[preferred], 'top', 'bottom', 'left', 'right']
    .filter((item, index, values): item is TooltipPlacement => values.indexOf(item) === index);
  const fits = ({ top, left }: Point) =>
    top >= VIEWPORT_PADDING &&
    left >= VIEWPORT_PADDING &&
    top + tooltip.height <= viewport.height - VIEWPORT_PADDING &&
    left + tooltip.width <= viewport.width - VIEWPORT_PADDING;
  const placement = order.find((item) => fits(candidates[item])) ?? preferred;
  const candidate = candidates[placement];
  const left = Math.max(
    VIEWPORT_PADDING,
    Math.min(candidate.left, viewport.width - tooltip.width - VIEWPORT_PADDING),
  );
  const top = Math.max(
    VIEWPORT_PADDING,
    Math.min(candidate.top, viewport.height - tooltip.height - VIEWPORT_PADDING),
  );
  const arrowX = Math.max(12, Math.min(trigger.left + trigger.width / 2 - left, tooltip.width - 12));
  const arrowY = Math.max(12, Math.min(trigger.top + trigger.height / 2 - top, tooltip.height - 12));
  return {
    placement,
    top,
    left,
    arrowX: `${arrowX}px`,
    arrowY: `${arrowY}px`,
  };
}
