export const SHELF_SWIPE_PX = 56;
export const SHELF_CHIP_PX = 36;

export type ShelfGesture = 'tap' | 'scroll' | 'dismiss';

/** Vertical motion on a chip scrolls the panel. Horizontal motion does not. */
export function chipScrollDelta(dx: number, dy: number): number {
  if (Math.abs(dy) < 1 || Math.abs(dx) > Math.abs(dy)) return 0;
  return -dy;
}

/** Horizontal motion dismisses. Vertical motion scrolls. A short move is a tap. */
export function classifyShelfGesture(dx: number, dy: number): ShelfGesture {
  const adx = Math.abs(dx);
  const ady = Math.abs(dy);
  if (adx < SHELF_SWIPE_PX && ady < SHELF_SWIPE_PX) return 'tap';
  if (adx > ady) return 'dismiss';
  return 'scroll';
}

/**
 * Panel height above the trigger. Caps at five chips.
 * Shrinks so the panel stays on screen; the list scrolls inside that height.
 */
export function panelRoomPx(triggerTop: number): number {
  const five = SHELF_CHIP_PX * 5 + 6 * 4;
  const above = Math.max(0, triggerTop - 8);
  if (above <= 0) return SHELF_CHIP_PX;
  return Math.min(five, above);
}
