import { inject, Injectable, InjectionToken, makeEnvironmentProviders } from '@angular/core';
import { Title } from '@angular/platform-browser';
import { TitleStrategy, RouterStateSnapshot } from '@angular/router';

export const DRYL_SITE_NAME = new InjectionToken<string>('DRYL_SITE_NAME');

@Injectable()
export class DrylDocumentTitleStrategy extends TitleStrategy {
  private readonly title = inject(Title);
  private readonly siteName = inject(DRYL_SITE_NAME);

  override updateTitle(snapshot: RouterStateSnapshot): void {
    const routeTitle =
      snapshot?.root != null ? (this.buildTitle(snapshot) ?? '') : '';
    const parts = [routeTitle, this.siteName, 'dryl.io'].filter(Boolean);
    this.title.setTitle(parts.join(' | '));
  }
}

export function provideDrylDocumentTitle(siteName: string) {
  return makeEnvironmentProviders([
    { provide: DRYL_SITE_NAME, useValue: siteName },
    { provide: TitleStrategy, useClass: DrylDocumentTitleStrategy },
  ]);
}
