import {
  afterNextRender,
  Component,
  ElementRef,
  EventEmitter,
  HostListener,
  inject,
  Injector,
  Input,
  Output,
  viewChild,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { IconComponent } from '../icon/icon.component';

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

@Component({
  selector: 'dryl-modal, app-modal',
  standalone: true,
  imports: [CommonModule, IconComponent],
  templateUrl: './modal.component.html',
  styleUrl: './modal.component.scss',
})
export class ModalComponent {
  @Input({ required: true }) title!: string;
  @Input() showActions = true;
  @Input() size: 'default' | 'wide' = 'default';
  @Input() flushBody = false;
  @Input() titleStyle: 'default' | 'alt' = 'default';

  @Output() readonly close = new EventEmitter<void>();
  @Output() readonly backdropClick = new EventEmitter<void>();

  private readonly dialog = viewChild<ElementRef<HTMLElement>>('dialog');
  private readonly injector = inject(Injector);

  constructor() {
    afterNextRender(() => this.focusInitial(), { injector: this.injector });
  }

  @HostListener('document:keydown', ['$event'])
  onDocumentKeydown(event: KeyboardEvent): void {
    const root = this.dialog()?.nativeElement;
    if (!root) return;
    if (event.key === 'Escape') {
      event.preventDefault();
      this.close.emit();
      return;
    }
    if (event.key !== 'Tab') return;
    const items = focusableIn(root);
    if (!items.length) return;
    const first = items[0];
    const last = items[items.length - 1];
    const active = document.activeElement;
    const inside = active instanceof HTMLElement && root.contains(active);
    if (event.shiftKey && (!inside || active === first)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && (!inside || active === last)) {
      event.preventDefault();
      first.focus();
    }
  }

  private focusInitial(): void {
    focusableIn(this.dialog()?.nativeElement)[0]?.focus();
  }
}

function focusableIn(root: HTMLElement | undefined): HTMLElement[] {
  if (!root) return [];
  return [...root.querySelectorAll<HTMLElement>(FOCUSABLE)].filter(
    (el) => !el.hasAttribute('disabled'),
  );
}
