export type ThemeTokenEntry = { drylVar: string };

const BASE_TO_RESOLVED: Record<string, string> = {
  '--background-primary-base': '--background-primary',
  '--background-secondary-base': '--background-secondary',
  '--background-tertiary-base': '--background-tertiary',
  '--list-hover-background-base': '--list-hover-background',
  '--border-primary-base': '--border-primary',
  '--border-secondary-base': '--border-secondary',
};

const DRYL_TOKEN_KEYS = [
  '--background-primary-base',
  '--background-secondary-base',
  '--background-tertiary-base',
  '--list-hover-background-base',
  '--border-primary-base',
  '--border-secondary-base',
  '--accent-primary',
  '--accent-secondary',
  '--accent-border',
  '--danger-primary',
  '--warning-primary',
  '--success-primary',
  '--info-primary',
  '--highlight-primary',
  '--text-primary',
  '--text-secondary',
  '--text-muted',
];

export const THEME_TOKEN_CATALOG: ThemeTokenEntry[] = DRYL_TOKEN_KEYS.flatMap(
  (drylVar) => {
    const resolved = BASE_TO_RESOLVED[drylVar];
    return resolved
      ? [{ drylVar }, { drylVar: resolved }]
      : [{ drylVar }];
  },
);