import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  EventEmitter,
  Input,
  Output,
  QueryList,
  ViewChildren,
} from '@angular/core';
import { IconComponent } from '../icon/icon.component';

export type DrylTabItem = {
  id: string;
  label: string;
  icon?: string;
  disabled?: boolean;
};

@Component({
  selector: 'dryl-tabs',
  standalone: true,
  imports: [IconComponent],
  templateUrl: './tabs.component.html',
  styleUrl: './tabs.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TabsComponent {
  @ViewChildren('tabButton') private readonly tabButtons!: QueryList<
    ElementRef<HTMLButtonElement>
  >;
  @Input() items: ReadonlyArray<DrylTabItem> = [];
  @Input() active = '';
  @Input() ariaLabel = 'Sections';
  @Input() orientation: 'horizontal' | 'vertical' = 'horizontal';
  @Output() readonly selected = new EventEmitter<string>();

  pick(item: DrylTabItem): void {
    if (!item.disabled) this.selected.emit(item.id);
  }

  onKeydown(event: KeyboardEvent, index: number): void {
    const previous = this.orientation === 'vertical' ? 'ArrowUp' : 'ArrowLeft';
    const next = this.orientation === 'vertical' ? 'ArrowDown' : 'ArrowRight';
    const step = event.key === previous ? -1 : event.key === next ? 1 : 0;
    const edge = event.key === 'Home' ? 0 : event.key === 'End' ? this.items.length - 1 : -1;
    if (!step && edge < 0) return;
    event.preventDefault();
    const target = edge >= 0 ? edge : this.nextEnabled(index, step);
    const item = this.items[target];
    if (!item || item.disabled) return;
    this.selected.emit(item.id);
    queueMicrotask(() => this.tabButtons.get(target)?.nativeElement.focus());
  }

  private nextEnabled(index: number, step: number): number {
    let target = index;
    for (let checked = 0; checked < this.items.length; checked += 1) {
      target = (target + step + this.items.length) % this.items.length;
      if (!this.items[target]?.disabled) return target;
    }
    return index;
  }
}
