import { CommonModule } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  HostBinding,
  Input,
  OnDestroy,
  signal,
  ViewChild,
  WritableSignal,
} from '@angular/core';
import {
  calculateTooltipPosition,
  type TooltipPlacement,
  type TooltipPosition,
} from './position/tooltip-position';

@Component({
  selector: 'dryl-tooltip, app-tooltip',
  imports: [CommonModule],
  templateUrl: './tooltip.component.html',
  styleUrl: './tooltip.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TooltipComponent implements OnDestroy {
  private static nextId = 0;
  private static activeTooltipId: WritableSignal<string | null>;

  private readonly tooltipId: string;
  private readonly hovered = signal(false);
  private readonly focused = signal(false);
  private positionFrame: number | null = null;
  private listeningForViewport = false;
  private readonly reposition = () => this.schedulePosition();

  @ViewChild('trigger', { read: ElementRef }) private trigger?: ElementRef<HTMLElement>;
  @ViewChild('tooltip', { read: ElementRef }) private tooltip?: ElementRef<HTMLElement>;

  readonly resolvedPlacement = signal<TooltipPlacement>('top');
  readonly tooltipPosition = signal<TooltipPosition | null>(null);

  constructor() {
    // Initialize static signal on first instance creation
    if (!TooltipComponent.activeTooltipId) {
      TooltipComponent.activeTooltipId = signal<string | null>(null);
    }
    
    this.tooltipId = `tooltip-${++TooltipComponent.nextId}`;
  }

  @Input() text: string | null = null;
  @Input() placement: TooltipPlacement = 'top';
  @Input() disabled = false;
  @Input() fullWidth = false;

  get isOpen(): boolean {
    if (this.hostDisabled) {
      return false;
    }
    if (TooltipComponent.activeTooltipId() !== this.tooltipId) {
      return false;
    }
    return this.hovered() || this.focused();
  }

  get hasContent(): boolean {
    const value = this.text?.trim() ?? '';
    return value.length > 0;
  }

  @HostBinding('class.is-block')
  get hostBlock(): boolean {
    return this.fullWidth;
  }

  @HostBinding('class.is-disabled')
  get hostDisabled(): boolean {
    return this.disabled || !this.hasContent;
  }

  handleMouseEnter(): void {
    if (this.hostDisabled) {
      return;
    }
    this.hovered.set(true);
    this.open();
  }

  handleMouseLeave(): void {
    this.hovered.set(false);
    this.closeIfIdle();
  }

  handleFocusIn(): void {
    if (this.hostDisabled) {
      return;
    }
    this.focused.set(true);
    this.open();
  }

  handleFocusOut(event: FocusEvent): void {
    this.focused.set(false);
    this.closeIfIdle();
  }

  ngOnDestroy(): void {
    this.closeIfIdle(true);
    if (this.positionFrame !== null) {
      cancelAnimationFrame(this.positionFrame);
    }
    this.stopViewportListeners();
  }

  private open(): void {
    TooltipComponent.activeTooltipId.set(this.tooltipId);
    this.startViewportListeners();
    this.schedulePosition();
  }

  private closeIfIdle(force = false): void {
    if (force || (!this.hovered() && !this.focused())) {
      if (TooltipComponent.activeTooltipId() === this.tooltipId) {
        TooltipComponent.activeTooltipId.set(null);
      }
      this.tooltipPosition.set(null);
      this.stopViewportListeners();
    }
  }

  private schedulePosition(): void {
    if (typeof window === 'undefined') return;
    if (this.positionFrame !== null) cancelAnimationFrame(this.positionFrame);
    this.positionFrame = requestAnimationFrame(() => {
      this.positionFrame = null;
      this.updatePosition();
    });
  }

  private updatePosition(): void {
    const trigger = this.trigger?.nativeElement.getBoundingClientRect();
    const tooltip = this.tooltip?.nativeElement.getBoundingClientRect();
    if (!trigger || !tooltip || !tooltip.width || !tooltip.height) return;
    const position = calculateTooltipPosition(
      trigger,
      tooltip,
      { width: window.innerWidth, height: window.innerHeight },
      this.placement,
    );
    this.resolvedPlacement.set(position.placement);
    this.tooltipPosition.set(position);
  }

  private startViewportListeners(): void {
    if (this.listeningForViewport || typeof window === 'undefined') return;
    window.addEventListener('resize', this.reposition);
    window.addEventListener('scroll', this.reposition, true);
    this.listeningForViewport = true;
  }

  private stopViewportListeners(): void {
    if (!this.listeningForViewport || typeof window === 'undefined') return;
    window.removeEventListener('resize', this.reposition);
    window.removeEventListener('scroll', this.reposition, true);
    this.listeningForViewport = false;
  }
}
