import {
  afterEveryRender,
  Component,
  ElementRef,
  EventEmitter,
  forwardRef,
  Input,
  Output,
  viewChild,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { selectChangeCommitted } from './select-change';

export type DrylSelectOption = {
  value: string;
  label: string;
  disabled?: boolean;
};

@Component({
  selector: 'dryl-select',
  standalone: true,
  templateUrl: './select.component.html',
  styleUrl: './select.component.scss',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => SelectComponent),
      multi: true,
    },
  ],
})
export class SelectComponent implements ControlValueAccessor {
  @Input() options: ReadonlyArray<DrylSelectOption> = [];
  @Input() label: string | null = null;
  @Input() ariaLabel: string | null = null;
  @Input() id: string | null = null;
  @Input() embedded = false;
  @Input() accentMix = false;
  @Input() fullWidth = true;
  @Input() value = '';
  @Input() disabled = false;
  @Output() valueChange = new EventEmitter<string>();
  @Output() blurred = new EventEmitter<void>();

  private readonly control = viewChild<ElementRef<HTMLSelectElement>>('control');
  private onChange: (value: string) => void = () => undefined;
  private onTouched: () => void = () => undefined;

  constructor() {
    // Native <select [value]> often stays on the first option when options paint
    // after the value binding (Appearance theme slots). @Input fields are not
    // signals, so afterRenderEffect never re-ran after Apply — use afterEveryRender.
    afterEveryRender({
      write: () => {
        const el = this.control()?.nativeElement;
        const want = this.value;
        const opts = this.options;
        if (!el || !opts?.length) return;
        if (![...el.options].some((row) => row.value === want)) return;
        if (el.value !== want) el.value = want;
      },
    });
  }

  handleChange(event: Event): void {
    const control = event.target as HTMLSelectElement;
    const nextValue = control.value;
    const active = typeof document === 'undefined' ? null : document.activeElement;
    if (!selectChangeCommitted(active, control, nextValue, this.value)) {
      if (control.value !== this.value && [...control.options].some((row) => row.value === this.value)) {
        control.value = this.value;
      }
      return;
    }
    this.value = nextValue;
    this.onChange(nextValue);
    this.onTouched();
    this.valueChange.emit(nextValue);
  }

  handleBlur(): void {
    this.onTouched();
    this.blurred.emit();
  }

  writeValue(value: string | null): void {
    this.value = value ?? '';
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }
}
