import { ChangeDetectionStrategy, Component, Input, ViewEncapsulation } from '@angular/core';

export type DrylSkeletonVariant =
  | 'text'
  | 'title'
  | 'image'
  | 'avatar'
  | 'button'
  | 'chip'
  | 'input';

/**
 * Shape-matched loading placeholder with a theme-token shimmer.
 * Spec: match final content geometry; shimmer ~1.2–1.6s linear; respect reduced motion.
 * Image variant fills a sized host (`block-size: 100%`, min 8rem).
 */
@Component({
  selector: 'dryl-skeleton',
  standalone: true,
  templateUrl: './skeleton.component.html',
  styleUrl: './skeleton.component.scss',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SkeletonComponent {
  @Input() variant: DrylSkeletonVariant = 'text';
  /** Optional inline-size override (e.g. `70%`, `8rem`). */
  @Input() width: string | null = null;
  /** Optional block-size override. */
  @Input() height: string | null = null;
  @Input() ariaLabel: string | null = 'Loading';
}
