import { Directive, ElementRef, inject, OnDestroy, OnInit } from '@angular/core';
import { bindScrollFriendlyRanges } from '../utils/scroll-friendly-range';

@Directive({
  selector: '[drylScrollFriendlyRange]',
  standalone: true,
})
export class ScrollFriendlyRangeDirective implements OnInit, OnDestroy {
  private readonly host = inject(ElementRef<HTMLElement>);
  private unbind: (() => void) | null = null;

  ngOnInit(): void {
    this.unbind = bindScrollFriendlyRanges(this.host.nativeElement);
  }

  ngOnDestroy(): void {
    this.unbind?.();
    this.unbind = null;
  }
}
