import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  forwardRef,
  Input,
  Injector,
  inject,
  viewChild,
  ViewEncapsulation,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { clipboardPlainText, insertClipboardText } from '../field-paste';

@Component({
  selector: 'dryl-input',
  standalone: true,
  templateUrl: './input.component.html',
  styleUrl: './input.component.scss',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => InputComponent),
      multi: true,
    },
  ],
})
export class InputComponent implements ControlValueAccessor {
  @Input() inputId = '';
  @Input() label: string | null = null;
  @Input() type = 'text';
  /** Prefer text + inputMode=url over type=url — Android long-press paste is unreliable on type=url. */
  @Input() inputMode: string | null = null;
  @Input() autocomplete: string | null = null;
  @Input() layout: 'inset' | 'stacked' = 'stacked';
  @Input() ariaLabel: string | null = null;
  @Input() readonly = false;
  @Input() placeholder: string | null = null;
  /** Invalid chrome without a helper line — prefer this over `error` when layout must not shift. */
  @Input() invalid = false;
  @Input() error: string | null = null;

  get showInvalid(): boolean {
    return this.invalid || !!this.error;
  }

  private readonly field = viewChild<ElementRef<HTMLInputElement>>('field');
  private readonly injector = inject(Injector);
  disabled = false;
  private model = '';
  /** Trust DOM after paste even if focus briefly left (Android long-press menu). */
  private pasteGuardUntil = 0;

  private onChange: (value: string) => void = () => {};
  onTouched: () => void = () => {};

  constructor() {
    afterNextRender(() => this.applyModel(), { injector: this.injector });
  }

  get errorId(): string {
    return `${this.inputId || 'dryl-input'}-error`;
  }

  writeValue(value: string | null): void {
    this.model = value ?? '';
    this.applyModel();
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }

  onInput(event: Event): void {
    this.model = (event.target as HTMLInputElement).value;
    this.onChange(this.model);
  }

  /** Pixel / Android: own the text insert so CD cannot wipe long-press paste. */
  onPaste(event: ClipboardEvent): void {
    const el = event.target as HTMLInputElement | null;
    if (!el) return;
    this.pasteGuardUntil = performance.now() + 750;
    const clip = clipboardPlainText(event);
    if (clip) {
      event.preventDefault();
      this.model = insertClipboardText(el, clip);
      this.onChange(this.model);
      return;
    }
    const sync = () => {
      this.model = el.value;
      this.onChange(this.model);
    };
    queueMicrotask(sync);
    requestAnimationFrame(sync);
    setTimeout(sync, 0);
    setTimeout(sync, 50);
  }

  private applyModel(): void {
    const el = this.field()?.nativeElement;
    if (!el) return;
    const guarded = performance.now() < this.pasteGuardUntil;
    const focused =
      typeof document !== 'undefined' && document.activeElement === el;
    if ((guarded || focused) && el.value !== this.model) {
      this.model = el.value;
      this.onChange(this.model);
      return;
    }
    if (el.value !== this.model) el.value = this.model;
  }
}
