const AXIS_LOCK_PX = 10;

export function bindScrollFriendlyRanges(root: ParentNode): () => void {
  const inputs = root.querySelectorAll('input[type="range"]');
  const cleanups: Array<() => void> = [];
  inputs.forEach((input) => {
    if (!(input instanceof HTMLInputElement)) return;
    let startX = 0;
    let startY = 0;
    let mode: 'undecided' | 'scroll' | 'slide' = 'undecided';
    const resetMode = () => {
      mode = 'undecided';
      input.style.pointerEvents = '';
    };
    const onStart = (e: TouchEvent) => {
      if (e.touches.length !== 1) return;
      const t = e.touches[0];
      startX = t.clientX;
      startY = t.clientY;
      mode = 'undecided';
      input.style.pointerEvents = '';
    };
    const onMove = (e: TouchEvent) => {
      if (e.touches.length !== 1) return;
      const t = e.touches[0];
      const dx = t.clientX - startX;
      const dy = t.clientY - startY;
      if (mode === 'undecided') {
        if (Math.abs(dx) < AXIS_LOCK_PX && Math.abs(dy) < AXIS_LOCK_PX) return;
        mode = Math.abs(dy) > Math.abs(dx) ? 'scroll' : 'slide';
      }
      if (mode === 'scroll') {
        e.preventDefault();
        input.style.pointerEvents = 'none';
      }
    };
    const onEnd = () => {
      resetMode();
    };
    input.addEventListener('touchstart', onStart, { passive: true });
    input.addEventListener('touchmove', onMove, { passive: false });
    input.addEventListener('touchend', onEnd, { passive: true });
    input.addEventListener('touchcancel', onEnd, { passive: true });
    cleanups.push(() => {
      input.removeEventListener('touchstart', onStart);
      input.removeEventListener('touchmove', onMove);
      input.removeEventListener('touchend', onEnd);
      input.removeEventListener('touchcancel', onEnd);
      resetMode();
    });
  });
  return () => {
    for (const fn of cleanups) fn();
  };
}
