import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  forwardRef,
  Input,
  Injector,
  inject,
  viewChild,
  ViewEncapsulation,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { clipboardPlainText, insertClipboardText } from '../field-paste';

@Component({
  selector: 'dryl-textarea',
  standalone: true,
  templateUrl: './textarea.component.html',
  styleUrl: './textarea.component.scss',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => TextareaComponent),
      multi: true,
    },
  ],
})
export class TextareaComponent implements ControlValueAccessor {
  @Input() inputId = '';
  @Input() placeholder = '';
  @Input() rows = 4;
  @Input() ariaLabel: string | null = null;
  @Input() set disabled(value: boolean) {
    this.disabledState = value;
  }
  get disabled(): boolean {
    return this.disabledState;
  }

  private readonly field = viewChild<ElementRef<HTMLTextAreaElement>>('field');
  private readonly injector = inject(Injector);
  private disabledState = false;
  private model = '';
  /** Trust DOM after paste even if focus briefly left (Android long-press menu). */
  private pasteGuardUntil = 0;
  private onChange: (value: string) => void = () => {};
  onTouched: () => void = () => {};

  constructor() {
    // Seed once after first paint if writeValue raced the view.
    afterNextRender(() => this.applyModel(), { injector: this.injector });
  }

  writeValue(value: string | null): void {
    this.model = value ?? '';
    this.applyModel();
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabledState = isDisabled;
  }

  onInput(event: Event): void {
    this.model = (event.target as HTMLTextAreaElement).value;
    this.onChange(this.model);
  }

  /**
   * Pixel / Android PWAs often insert clipboard text without a reliable `input`
   * event. Reading `el.value` during `paste` is still the pre-insert string —
   * syncing that into Angular then lets CD wipe the real paste. Prefer the
   * clipboard payload + preventDefault, and keep a short DOM-trust guard.
   */
  onPaste(event: ClipboardEvent): void {
    const el = event.target as HTMLTextAreaElement | null;
    if (!el) return;
    this.pasteGuardUntil = performance.now() + 750;
    const clip = clipboardPlainText(event);
    if (clip) {
      event.preventDefault();
      this.model = insertClipboardText(el, clip);
      this.onChange(this.model);
      return;
    }
    const sync = () => {
      this.model = el.value;
      this.onChange(this.model);
    };
    queueMicrotask(sync);
    requestAnimationFrame(sync);
    setTimeout(sync, 0);
    setTimeout(sync, 50);
  }

  private applyModel(): void {
    const el = this.field()?.nativeElement;
    if (!el) return;
    const guarded = performance.now() < this.pasteGuardUntil;
    const focused =
      typeof document !== 'undefined' && document.activeElement === el;
    if ((guarded || focused) && el.value !== this.model) {
      this.model = el.value;
      this.onChange(this.model);
      return;
    }
    if (el.value !== this.model) el.value = this.model;
  }
}
