import { Component, HostBinding, Input } from '@angular/core';

@Component({
  selector: 'dryl-icon, app-icon',
  standalone: true,
  template: '',
  styleUrl: './icon.component.scss',
})
export class IconComponent {
  @Input({ required: true }) name!: string;
  @Input() className = '';
  @Input() ariaLabel: string | null = null;
  @Input() size: 'normal' | 'small' = 'normal';

  @HostBinding('attr.role')
  get hostRole(): string | null {
    return this.accessibleName ? 'img' : null;
  }

  @HostBinding('attr.aria-label')
  get hostAriaLabel(): string | null {
    return this.accessibleName;
  }

  @HostBinding('attr.aria-hidden')
  get hostAriaHidden(): 'true' | null {
    return this.accessibleName ? null : 'true';
  }

  @HostBinding('class')
  get hostClasses(): string {
    const classes = ['material-symbols-outlined'];
    if (this.size === 'small') classes.push('icon-small');
    if (this.className) classes.push(this.className);
    return classes.join(' ');
  }

  private get accessibleName(): string | null {
    const label = this.ariaLabel?.trim();
    return label ? label : null;
  }

  @HostBinding('textContent')
  get iconText(): string {
    return this.name;
  }
}
