import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  Output,
  ViewEncapsulation,
} from '@angular/core';

/** @deprecated Prefer `ghost` — `tertiary` is a backward-compatible alias with identical styling. */
export type ButtonVariantInput = 'primary' | 'secondary' | 'ghost' | 'tertiary' | 'danger';

export type ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger';

export type ButtonSize = 'sm' | 'md' | 'lg';

export function resolveButtonVariant(variant: ButtonVariantInput): ButtonVariant {
  return variant === 'tertiary' ? 'ghost' : variant;
}

@Component({
  selector: 'dryl-button, app-button',
  imports: [],
  templateUrl: './button.component.html',
  styleUrl: './button.component.scss',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ButtonComponent {
  /**
   * Visual style. Use `ghost` for borderless actions; `tertiary` is deprecated but still supported.
   * See projects/dryl/ui/docs/BUTTON-VARIANTS.md.
   */
  @Input() variant: ButtonVariantInput = 'primary';
  @Input() size: ButtonSize = 'md';
  @Input() type: 'button' | 'submit' | 'reset' = 'button';
  @Input() disabled = false;
  @Input() ariaLabel: string | null = null;
  @Input() routerLink: string | string[] | null = null;
  @Input() label: string | null = null;
  @Input() leftIcon: string | null = null;
  @Input() rightIcon: string | null = null;
  @Input() fullWidth = false;
  @Input() highlighted = false;

  @Output() readonly pressed = new EventEmitter<MouseEvent>();

  @HostBinding('class.is-block')
  get hostBlock(): boolean {
    return this.fullWidth;
  }

  @HostBinding('attr.data-variant')
  get dataVariant(): ButtonVariant {
    return resolveButtonVariant(this.variant);
  }

  get classAttr(): string {
    const resolved = resolveButtonVariant(this.variant);
    const cls = ['dryl-button', resolved, `size-${this.size}`];
    if (this.variant === 'tertiary') {
      cls.push('tertiary');
    }
    if (this.leftIcon) cls.push('has-left-icon');
    if (this.rightIcon) cls.push('has-right-icon');
    if (this.fullWidth) cls.push('is-block');
    if (this.highlighted) cls.push('is-highlighted');
    return cls.join(' ');
  }

  get hasStructuredContent(): boolean {
    return Boolean(this.label || this.leftIcon || this.rightIcon);
  }

  handleClick(event: MouseEvent): void {
    if (this.disabled) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }

    this.pressed.emit(event);
  }
}
