import { NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  OnChanges,
  ViewEncapsulation,
  computed,
  contentChildren,
  input,
  signal,
} from '@angular/core';
import { DrylCellDirective } from './dryl-cell.directive';
import type { DrylColumn } from './dryl-column.types';
import { type SortDir, sortRows } from './dryl-table-sort';

@Component({
  selector: 'dryl-table, app-dryl-table',
  standalone: true,
  imports: [NgTemplateOutlet],
  templateUrl: './dryl-table.component.html',
  styleUrl: './dryl-table.component.scss',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DrylTableComponent implements OnChanges {
  @Input({ required: true }) columns: DrylColumn[] = [];
  readonly rows = input.required<Record<string, unknown>[]>();
  @Input() emptyLabel = 'No rows.';
  @Input() tableId = '';
  @Input() panel = false;
  @Input() columnLayout = true;
  @Input() initialSortKey = '';
  @Input() initialSortDir: SortDir = 'asc';

  @HostBinding('class.dryl-table-host')
  readonly hostClass = true;

  @HostBinding('attr.data-table-id')
  get dataTableId(): string | null {
    return this.tableId || null;
  }

  private readonly cellTemplates = contentChildren(DrylCellDirective);
  private readonly sortKey = signal('');
  private readonly sortDir = signal<SortDir>('asc');
  private sortReady = false;

  readonly displayRows = computed(() => {
    const key = this.sortKey();
    const rows = this.rows();
    if (!key) {
      return rows;
    }
    return sortRows(rows, key, this.sortDir());
  });

  ngOnChanges(): void {
    if (!this.sortReady && this.initialSortKey) {
      this.sortKey.set(this.initialSortKey);
      this.sortDir.set(this.initialSortDir);
      this.sortReady = true;
    }
  }

  templateFor(columnId: string): DrylCellDirective | undefined {
    return this.cellTemplates().find((entry) => entry.columnId === columnId);
  }

  cellValue(row: Record<string, unknown>, column: DrylColumn): unknown {
    return row[column.id];
  }

  /** Stable row identity so re-sorts/polling reorders don't reshuffle the DOM by position. */
  rowKey(row: Record<string, unknown>, index: number): unknown {
    return row['id'] ?? row['reportId'] ?? row['ticketKey'] ?? index;
  }

  toggleSort(column: DrylColumn): void {
    if (!column.sortable) {
      return;
    }
    if (this.sortKey() !== column.id) {
      this.sortKey.set(column.id);
      this.sortDir.set('asc');
      return;
    }
    this.sortDir.update((dir) => (dir === 'asc' ? 'desc' : 'asc'));
  }

  sortIcon(column: DrylColumn): string {
    if (this.sortKey() !== column.id) {
      return 'unfold_more';
    }
    return this.sortDir() === 'asc' ? 'arrow_upward' : 'arrow_downward';
  }

  colClass(column: DrylColumn): string {
    return `dryl-col-${column.id}`;
  }
}