/** Clears inline theme overrides applied by Theme Preview on :root. */
export function clearVscodeThemeFromRoot(
  root: HTMLElement | null | undefined = globalThis.document?.documentElement,
): void {
  if (!root?.style) {
    return;
  }
  const style = root.style;
  const toRemove: string[] = [];
  for (let index = 0; index < style.length; index += 1) {
    const name = style.item(index);
    if (name.startsWith('--') || name === 'color-scheme') {
      toRemove.push(name);
    }
  }
  for (const name of toRemove) {
    style.removeProperty(name);
  }
}