import { Directive, Input, TemplateRef } from '@angular/core';

@Directive({
  selector: 'ng-template[drylCell]',
  standalone: true,
})
export class DrylCellDirective {
  @Input({ alias: 'drylCell', required: true }) columnId!: string;

  constructor(readonly templateRef: TemplateRef<{ $implicit: Record<string, unknown> }>) {}
}