/** Pixel / Android PWA paste helpers — long-press often skips a reliable `input` event. */

export type PasteableField = {
  value: string;
  selectionStart: number | null;
  selectionEnd: number | null;
  setSelectionRange: (start: number, end: number) => void;
};

/** Insert clipboard text at the caret (caller should preventDefault first). */
export function insertClipboardText(el: PasteableField, clip: string): string {
  const start = el.selectionStart ?? el.value.length;
  const end = el.selectionEnd ?? el.value.length;
  const next = `${el.value.slice(0, start)}${clip}${el.value.slice(end)}`;
  el.value = next;
  const caret = start + clip.length;
  try {
    el.setSelectionRange(caret, caret);
  } catch {
    /* selection can throw on some WebViews mid-composition */
  }
  return next;
}

/** Plain text from a paste event, if the platform exposes it. */
export function clipboardPlainText(event: ClipboardEvent): string {
  try {
    return event.clipboardData?.getData('text/plain') ?? '';
  } catch {
    return '';
  }
}
